quests[84121] = { id = 84121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Insurance", description = "There are too many Darkfuse guardin' this place for us to sneak around them. We're gonna have to thin 'em out the old fashioned way.\n\nTake out as many Darkfuse as you can. Me and Gazlowe will do some reconnaissance.", progress = "I don't need those goons breathin' down our necks while we're working things out here.", completion = "That'll do for now. At least we've got some space to figure out a plan.", objectives = "Slay 10 Darkfuse on the Kaja'Coast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84122] = { id = 84122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cut the Cameras", description = "Gallywix ain't an idiot. He's got those surveillance birds keepin' an eye on this entire area.\n\nWe're gonna need to bring 'em offline if we wanna keep a low profile--and by that, I mean smash 'em to itty bitty pieces.\n\nIf you need help grabbin' them outta the air, use this auto-grappler. Oh, and scoop some of their parts up for me when you're done. I've got an idea.", progress = "I'm not sure why they're watchin' a mine this closely, but we need to make sure they got less eyes on it.", completion = "I got this B.I.R.D. mostly gutted.\n\nBetween the two of us, we should be able to break these parts down and use 'em to make some new internals.", objectives = "Collect 6 Handfuls of B.I.R.D. Parts from Surveillance B.I.R.D.s on the Kaja'Coast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84123] = { id = 84123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test", description = "Test" }
quests[84127] = { id = 84127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blacksmithing Services Requested", description = "Greetings, {class}. The Artisan's Consortium is looking for highly skilled artisans to complete orders for local clientele. \n\nIf you think your work is up to the standards and quality we expect, please take a at shot at filling out some of our public orders. You can also fill orders for patrons of your own, guild orders, or personal orders. \n\nCome speak with me once you've completed your designs, and may the wind guide your hands and heart.", progress = "Come speak with me once you've completed your designs, and may the wind guide your hands and heart.", completion = "Thank you for filling those orders. Our customers will be most pleased.", objectives = "Fill Blacksmithing Crafting Orders for the Artisan's Consortium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
