quests[84334] = { id = 84334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warn the Detective", description = "Welcome back, {name}.\n\nI saw the detective headed west. Hurry up and warn him before the shapeshifter comes for him too!", completion = "A shapeshifter? Hah! Poppycock!", objectives = "Warn Detective Jones about the shapeshifter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84336] = { id = 84336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spot the Difference", description = "Look, I'm the real detective. You believe me, right?\n\nI know--ask me anything. The good people here will be able to corroborate my story and we'll prove that I'm me.", progress = "This is preposterous...", completion = "Thank you so much for solving the case, {name}!\n\nHopefully, this event will be calmer now.", objectives = "Solve the case of the shapeshifting demon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84352] = { id = 84352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No More Walkin' Here", description = "We gotta do something about how long it's taking to get you around. Luckily, I know just the gal. Go meet Nanny Talullah at the Caddy Shack and see if she'll lend you some wheels.", completion = "You need a car? Of course we can get you a car! We have so many cars! Here, I even have some spare keys right here!", objectives = "Meet Nanny Talullah on the third floor at the Caddy Shack.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84363] = { id = 84363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tweasure Hunt", description = "I know! We could use da stick to look for tweasures!\n\nYou and Enzo go check da other ruins. Find somefing really cool!\n\nI'll meet you back at da parties.", progress = "Did you find any tweasure?", completion = "Wow, now this is real tweasure!", objectives = "Use the Torch of Pyrreth to search for treasure around the ruins of Tanaris.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84365] = { id = 84365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something on the Horizon", description = "Brann's scouts have reported sightings of reinforcements approaching the shores of Khaz Algar.\n\nHe's put out the call for adventurers to join him in Dornogal.", completion = "I've 'eard reports o' reinforcements approaching the isle. Ye know Khaz Algar inside and out--they'll need yer expertise.", objectives = "Speak to Brann Bronzebeard in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84367] = { id = 84367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Time to Come Together", description = "We ought tae be getting a whole fleet o' reinforcements soon. Just in time, I hear Alleria and Anduin are back in Dornogal.\n\nIf I know Moira, she'll already be workin' with 'em tae figure out our next move. She knows how tae lead like a gryphon knows how tae fly. Best go find her before she comes looking for ye.", completion = "Perfect timing. I've got good news for the first time since we crashed here.", objectives = "Speak to Moira Thaurissan in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84370] = { id = 84370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Key to Success", description = "<A Cipher Key? Elise Starseeker might know what to do with this.>", progress = "This map makes no sense... Champion! Good tidings I hope?", completion = "Astounding! This is what I've been missing. \n\nThe map Finley found is a cipher. But this key, it's incomplete... If you find any more out there, please bring them to me. I will decipher this map, or my name isn't Elise Starseeker.", objectives = "Bring the Archaic Cipher Key to Elise Starseeker in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84371] = { id = 84371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lorewalking: The Blade and the High Priest", description = "Xal'atath, the Harbinger of Void, is a cunning and dangerous foe. She has been careful to make her presence known only to a precious few.\n\nWe first learned of her during the Legion's third invasion of Azeroth, but whispers say she has been around since long, long before that. \n\nThis is a story of power, darkness, and deceit. Join me and I will tell you the tale of Xal'atath's mysterious past.", completion = "Xal'atath was a powerful weapon and a... talkative presence.", objectives = "Follow Cho's guidance to learn the story of Xal'alath's past.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84376] = { id = 84376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Property Devalued", description = "<You come across a wanted poster that has been nailed on top of a for rent sign.>\n\nWANTED: Seeking able-bodied adventurer to work as security for local apartment complex.\n\nMust be capable of not dying.\n\nREWARD: Free room and board in exchange for services rendered.\n\nInterested parties should inquire upstairs at the nearby Barrelbottom Apartments for further details.", progress = "That Moz is driving me crazy! Maybe you can talk some sense into him.", completion = "I didn't think anyone would actually show up. You here about the free room?\n\nYou didn't say nothin' to Barrelbottom, didja?", objectives = "Visit Barrelbottom Apartments and inquire about a room to rent.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84378] = { id = 84378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renter's Insurance", description = "It's bad enough that the old skinflint landlord is letting this place slowly fall apart, but now we got even bigger problems. \n\nRecently, those would-be gangsters up the road, the Underriders, went from petty theft and noise complaints to being a heavily armed menace. They've started trashing the place, and even attackin' us directly!\n\nWhat's worse, anyone who can't afford to move out are evicted for the damage those thugs caused instead.\n\nYou keep us safe, you can crash here free of charge.", progress = "I can't keep up with all these repairs. Someone needs to do something about those bikers!", completion = "You're back.\n\n <Keara winces from her injuries.>\n\nYour timing coulda been better.", objectives = "Kill 12 Underrider biker gang members.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84379] = { id = 84379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tenant Trouble", description = "<Gabi waves you over urgently.\n\nThe small goblin wrings her hands together nervously trying to find the words to explain her concern.>\n\nSome goblins aren't moving out--they're being kidnapped. I know it. \n\nMy friends wouldn't have moved. They wouldn't.\n\n<Gabi looks up at you imploringly with misty eyes.>\n\nPlease help, {class}. Please?", completion = "Everyone rescued. Only to be attacked again.\n\nWe can't let this stand, {name}.", objectives = "Rescue 8 Captured Tenants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84380] = { id = 84380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons Cash", description = "<Inside the weapons crate you find a crumpled note written to the Underriders.>\n\nGood to see you're putting your new toys to good use. These little squatters are leaving in droves thanks to you guys!\n\nKeep up the good work and there's more where this came from. Just try not to burn the whole place down. Can't rent out an empty lot, haha!\n\nSigned,\nM.B.B.", progress = "Find something?", completion = "A letter for the Underriders? I think I know this signature...\n\nIt's that wormy landlord, Moz Barrelbottom!", objectives = "Destroy Underrider equipment throughout the compound.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84381] = { id = 84381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renegotiations", description = "That settles it! I think we both know who's responsible for this mess. It's that bastard landlord, Moz Barrelbottom!\n\nSoon as the Underriders were dealt with, he sent his goon Jarvis on a rampage. Looks like if he can't scare us out, he's going to force us out!\n\n<Keara spits on the ground in disgust.>\n\nHe won't scare us so easily.\n\nYou're pretty tough, {name}. Moz's office is just across the street. Go show him he's messin' with the wrong goblins!", progress = "We'll be fine here. You just go deal with Moz!", completion = "Hah! That will show the old skinflint who's in charge. And with this deed, he can't threaten us with nothin'!\n\nYou did good. I think you've earned that free room alright.", objectives = "Defeat Jarvis Bonebreaker and collect the Barrelbottom Deed from Moz Barrelbottom in his third floor office across the street.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84392] = { id = 84392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungry in Hollow", description = "Hey. You looking for a great meal?\n\nWilling to wade through the mud to get it?\n\nGo see Dolena. She'll sort you out. Don't bother trying to convince her to leave that hollow, though. Believe me--we've all tried. Why someone would leave the safety of the light for that...\n\nShe seems to do alright, though.", completion = "Ah, another one. You here on purpose?", objectives = "Seek out Dolena in Growling Hollow", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84393] = { id = 84393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da Stick of Revealing", description = "Awwight, it's time to try da Stick of Reveawing!\n\nFowwow me.", progress = "A good sleuf knows how to use all da tools.", completion = "Sooo coooool!\n\n<Maru and Enzo exchange looks, eyebrow wiggles, and nods.>\n\nWe fink you should hold onto the tweasure-finding stick. You're a real good sleuf and maybe you can find more tweasures for us!", objectives = "Follow Maru, then use the Torch of Pyrreth on brazier outside the Ruins of Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84403] = { id = 84403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Small Bundle of Goods", objectives = "Task completed. The Council rewards you for assisting with earthen reunification.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84404] = { id = 84404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Small Bundle of Goods", objectives = "Task completed. The Council rewards you for assisting with earthen reunification.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84409] = { id = 84409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For the Valorous", objectives = "The Arathi truly appreciate all your help in this dangerous land. Please accept this symbol of our gratitude.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84419] = { id = 84419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To da Ruins!", description = "You found my brovver's sleufing fingy!\n\n<Maru holds it up with reverence.>\n\nDa Stick of Reveawing! Dis fing can turn on da lights, melt stuff, and even unlock ANSHENT TWEASURE. And all you gotta do is hold it up!\n\nWe wuz gonna try it on dis fing outside the Wuins of Uldum. Wanna come?", completion = "Weady for adventure?", objectives = "Meet Maru and Enzo outside the Ruins of Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84423] = { id = 84423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shaking the Dust Off", description = "Wow, you look really strong! Would you be able to help me?\n\nMy parents were killed by the mean kobyss. When I came here, I left my favorite, most well loved teddy ever behind. \n\nCould you go get it for me?", completion = "Welcome back to the land of the living, {class}. \n\nThere is much for you to catch up on.", objectives = "Retrieve Alyza's Much Loved Teddy Bear from the Hungering Pool in Hallowfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84424] = { id = 84424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forward, to Adventure!", description = "We are free, {class}. Free to do whatever it is we wish.\n\nThrough the portal lies the rest of your life.\n\nA member of the bronze dragonflight will help you on your journey.", completion = "Time to catch you up, {name}!", objectives = "Use the portal in the War Creche to get to Chromie.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84426] = { id = 84426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waterlogged Celebration Crate", description = "<The crate is soaking wet, but the insides might be salvageable. Alyx would appreciate the supplies returned.>", progress = "Yes?", completion = "Oh, you found a missing crate! Wonderful!\n\nI really appreciate you returning these. If you find any more, please bring them to me.", objectives = "Return the Waterlogged Celebration Crate to Alyx.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84429] = { id = 84429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Construct Containment" }
quests[84430] = { id = 84430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Crusade", description = "I swore my life to protect Beledar... and now a new star sings to us from the sea.\n\nI know not what this means for the Arathi, but I do know that letting these foul creatures of the deep snatch up pieces of it is likely to lead to ill. \n\nKill them with extreme prejudice and recover any pieces of the crystal in their possession.", progress = "Have you recovered the Crystal Fragments?", completion = "May Beledar's kin prosper now.", objectives = "Recover 10 Crystal Fragments and 30 Crystal Chunks from the Naga forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84432] = { id = 84432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Longship Landing", description = "These Bloodwake vrykul have no regard for us or our research. Even when we tried to share our discoveries with them, we were attacked! \n\nThey do not care that we mean the isle no harm--they want us to leave.\n\nBut we cannot leave now. There is so much more to discover! Someone must show them that we're not going to go just yet and that they should leave us alone.\n\nWe need to show them we will fight back.", progress = "Did you convince them to leave us alone yet?", completion = "I am not one to promote violence as a solution, but sometimes force is the only option.", objectives = "Eliminate 15 Bloodwake Vrykul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84435] = { id = 84435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nola's Last Wish", description = "Greetings, {name}! Could you check in with Lashk?\n\nHe seemed upset about something.", progress = "The stories Nola could tell...", completion = "It is comforting to hear that she will rest well now.\n\nI will be telling this story for many years, {name}. Thank you.", objectives = "Solve Lashk's mystery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84438] = { id = 84438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Easy Win", objectives = "Seems fortune favors the bold--and the skilled at cards. Our friend Millhouse wasn't exactly happy to part ways with this scroll, or all of the rest of his belongings for that matter.\n\nTake it, {race}. It's the least I can do for everything you did for the Dalaran survivors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84439] = { id = 84439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaja'Conclusions", description = "You've really helped me out here, {name}, but I need one more teeny tiny favor from you. \n\n<Jazz hands over an envelope stuffed to the brim with schematics and paper reports.>\n\nCould ya get this to my contract agent, Kory Hoxx? He'll get it to HQ. You'll probably catch him in the Incontinental Hotel, putting up more gig sheets.", progress = "Can't ya see I'm a little busy here? Recruitment's hard work, ya know!", completion = "Oh, Jazz has an update? Well why didn't ya say so!\n\n<Kory snatches the envelope, tearing it open and looking at the report.>\n\nHe needs HOW MANY people?!", objectives = "Deliver Jazz's Report to Kory Hoxx in the Incontinental Hotel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84442] = { id = 84442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invitation to the Spirit Festival", completion = "You made it!\n\nAs for getting to the Wandering Isle... are you ready for a hot air balloon ride?", objectives = "Meet Aysa Cloudsinger in Stormwind near the hot air balloon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84444] = { id = 84444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invitation to the Spirit Festival", completion = "You made it!\n\nBet you were wondering how we'd get to the isle... well, are you ready for a hot air balloon ride?", objectives = "Meet Ji Firepaw in Orgrimmar by the hot air balloon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84446] = { id = 84446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renown of Khaz Algar", description = "There is still much we still need tae do to aid Khaz Algar.\n\nBut I dunnae know much about this land past the realms of earthen.\n\nI'll have to refer ye to Faerin Lothar tae see what Hallowfall may need.\n\nTalk to her an' see if she needs any help. Ye already are acquainted, aren't ye?", completion = "Good to see you again, {name}. \n\nWe have a lot of work to do.", objectives = "Speak with Faerin Lothar in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84451] = { id = 84451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wanderers", completion = "Oh, it's so good to see dad!\n\nBut... where are all the festivities? Why does he look so worried?", objectives = "Ride the hot air balloon to the Wandering Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84452] = { id = 84452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wanderers", completion = "Oh, it's so good to see dad!\n\nBut... where are all the festivities? Why does he look so worried?", objectives = "Ride the hot air balloon to the Wandering Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84453] = { id = 84453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Dai-Lo Farmstead", description = "My brother Chon Po has been trying to rally everyone. He sent out handwritten invitations to each village. Can you believe that? He's a brewmaster--he should've sent brew!\n\nDai-Lo Farmstead was like a second home to us. Chon Po and I spent half our childhood there, helping with the harvests. It's where we made our very first drinks.\n\nLet's give the Dai-Lo villagers a big hit of nostalgia, and something new--as a teaser for what's to come at the festival.", completion = "Good news! Some were preparing to go to the festival, so we don't have to convince the whole village!\n\nBad news--there's a big problem in the fields. The virmen are back at it again.", objectives = "Journey to Dai-Lo Farmstead in the Wandering Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84454] = { id = 84454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tide of Virmen", description = "I was hoping for a heartier welcome when we arrived. Unfortunately, many of the villagers are occupied in the farmland. The harvest is in full swing, and so are the virmen.\n\nWe've fought these pests all my life. I don't know how they keep coming!\n\nChon Po and I are busy setting up the drink tasting. Can you take care of the problems in the field?", progress = "The Rows sound a little busy!", completion = "No doubt the virmen will be back, but now we can celebrate.\n\nWe'll bring some of the fresh harvest to the festival.", objectives = "Take back The Rows by killing virmen, harvesting produce, and helping farmers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84455] = { id = 84455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Big Bertha", description = "I love Chen's idea to entice the villagers with a brew tasting. I'm surprised I didn't think of it first!\n\nMy friends were hoping to take a large portion of the harvest to the festival. But Big Bertha is missing! We need her if we ever hope to haul back all the food and drink in time.\n\nThe villagers say she suddenly broke from her cart and disappeared underground.\n\nI'm worried. She may be large, but she has a soft heart. Can you go find her?", completion = "If push came to shove, I'm sure Big Bertha would've trampled that virmen. But I'm glad you saved her the stress.", objectives = "Find and save Big Bertha in The Rows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84456] = { id = 84456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Morning Breeze", description = "Chon Po said he sent several invitations to the villagers of Morning Breeze, but nobody has shown up.\n\nThat's very strange. They're usually the ones most excited about the Spirit Festival. They'll use any excuse to make and set off their fireworks!\n\nSomething must have happened. Let's go see.", completion = "Oh no! Their fireworks have gone missing. No wonder!", objectives = "Journey to Morning Breeze Village in the Wandering Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84457] = { id = 84457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Morning Breeze", description = "Chon Po said he sent several invitations to the villagers of Morning Breeze, but nobody showed up.\n\nThat's odd. They're usually the ones most excited about the Spirit Festival. Any excuse to make and set off their fireworks!\n\nSomething must be up. Let's find out.", completion = "Well that explains that--their fireworks are missing!", objectives = "Journey to Morning Breeze Village in The Wandering Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84458] = { id = 84458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Devil's in the Details", description = "Let's investigate the village for signs of mischief. I don't believe that the fireworks were simply misplaced. Shisai is a watchful pandaren and this is his big contribution to the festival.\n\nThe theft must have happened recently. Someone must have seen something.", completion = "Well, the case is more cut and dry than I thought. Everything points toward the hozen!", objectives = "Search for 3 clues about the missing fireworks in Morning Breeze Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84459] = { id = 84459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scamps Ain't It!", description = "Shisai said the fireworks were in a barrel... \n\n<Ji paws at his face.> \n\nAnd... he likely put them in the wrong barrel. Amidst the festival's extensive preparation, it'd be a miracle if none of the goods were crossed.\n\nWell then, let's search the barrels! It won't take long.", progress = "There sure are a lot of barrels...", completion = "Hmm... no fireworks in these barrels. There are more barrels in town... but what are the chances?", objectives = "Search 8 Wooden Barrels in Morning Breeze Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84460] = { id = 84460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Red Hand or Herring?", description = "Every clue points at the hozen stealing the fireworks! It is as Ji said. They've done it before--they'll do it again.\n\nLet us confront them right now.", progress = "It can only be the hozen who have done it!", completion = "Oh! \n\n<Aysa blushes.>\n\nWell, this is certainly unexpected. I am pleasantly surprised.", objectives = "Confront Huk Huk, the hozen chieftain, in Fe-Feng Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84461] = { id = 84461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Not a Spirit Festival Without Spirits", description = "<The crane bears a letter. It's from Li Li.>\n\nSomething's wrong at the Temple of Five Dawns. I need your help. Please come as soon as you can!", completion = "I'm glad you came quickly, {name}! I can always rely on Mr. Crane to deliver messages as fast as the wind.\n\nBut speaking of the wind...", objectives = "Meet Li Li Stormstout in the Temple of Five Dawns.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84462] = { id = 84462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patterns in Static", description = "I can't find any of the spirits in the temple. How are we going to have a Spirit Festival with no spirits?\n\nToday is a celebration for all four of the elemental spirits, but perhaps they also think today is just another day. We need to find them and tell them otherwise!\n\nLook, is this the wind spirit's trail? Maybe it will lead us to Dafeng... who can lead us to the others.", progress = "<Dafeng floats, waiting for something.>", completion = "<Dafeng spins in a circle, delighted, but quickly comes to a halt. He seems to be looking for the other spirits. Perhaps he needs help?>", objectives = "Collect 30 Remnants of Wind and use their power to find Dafeng in the Temple of Five Dawns.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84463] = { id = 84463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Codependency", progress = "Did you and Jojo find the rest of the spirits? Dafeng led me here... but I'm not sure why yet.", completion = "You and Jojo did it! Thank you.\n\nNow, Huo is the last missing spirit. Why did Dafeng lead me to a pool? Water and fire don't mix...", objectives = "Free Shu and Wuguo by defeating the Mud Amalgam in Pei-Wu Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84464] = { id = 84464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost My Spark", description = "Dafeng led me here, but then he flew away. I think he senses Huo, the spirit of fire, nearby.\n\nWhy are all the spirits in such a state today? The festival is for them, after all. I was anxious about returning home, but didn't know why. The spirits have always reflected the truth about the isle and its pandaren. If they're agitated, something must be wrong... or something has to change.\n\n<Li Li sighs and shakes her head.>\n\nFor now, we need to find Huo, and quickly. This steam trail must be his.", progress = "We need to find Huo and help him!", completion = "Huo's back to his old self!\n\nI feared the worst when I saw that Huo had come here. I hope he knows that we remembered him, and that we would never abandon him.\n\nThank you, {name}. We did it, for every spirit.", objectives = "Follow the trail of steam to find Huo, the Ancient Spirit of Fire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84465] = { id = 84465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Water and Blood", progress = "This place brings back so many memories.", completion = "Honestly, I missed dad more than I wanted to admit. It's been good to see him again.", objectives = "Gather 10 Blue Poppies and slay 10 Thornbranch Scamps in the Wood of Staves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84466] = { id = 84466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thousands of Years Ago...", completion = "<Li Li beams, unable to contain her excitement.> \n\nLorewalker Cho is here! So is Yu'lon!\n\nSo this means that Shen-zi Su actually returned to the waters of Pandaria? I can't believe it!", objectives = "Return to Wu-Song Village to begin the Spirit Festival.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84467] = { id = 84467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Was Home", description = "{name}!\n\nI cannot believe my eyes--Shen-zin Su, the Wandering Isle? Here?\n\nAnd his return to the shores of his birth coincided with the annual Spirit Festival? This cannot be a coincidence. You must have restored some sense of purpose and peace to him--and within everyone here as well.\n\nI have much to explore here. But first, we must celebrate this reunion! My dear friends!", progress = "I never thought I would witness Shen-zin Su's return to Pandaria in my lifetime.", completion = "I barely have the words to express what this means to me, {name}--what it means to us all. Thank you.", objectives = "Celebrate the Spirit Festival in Wu-Song Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84468] = { id = 84468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brew You One Better", description = "Ready for the brew tasting? We've caught the attention of a small crowd already.\n\nI've got something that will send their heads spinning--ingredients they've never even heard of before, and impeccable technique...\n\n<With a flourish, Chen places a ribbon of cucumber on a drink.>", progress = "<Chen quietly observes the villagers' reactions.>", completion = "<Chen is actually smiling, despite the villagers' tentative reactions.>\n\nNew tastes take time to appreciate. The citrus will rest in their minds--what fruit is it exactly? A sweet lemon? Or a sour melon? It is our nature to seek to understand the unfamiliar.\n\nThey'll be back for more--I know it. After all, the Spirit Festival is about celebrating new adventures!", objectives = "Distribute Chen and Chon's homebrews to the villagers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84469] = { id = 84469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Pet Bingo", description = "Well, hi there! The grand master pet tamers from Pandaria have posted a challenge to find certain battle pets on this fancy-lookin' bingo card. \n\nAll we have to do is find the pet that goes to the riddle and note it down on our bingo cards, but I'm having a hard time with the last two. It's quite easy to spot the normal pets, but these bingo cards require us to find special versions of the creatures.\n\nHmm... They didn't say anything in the rules about getting outside help. Care to help a friend out?", progress = "Have you any luck in finding the battle pets?", completion = "Hey, thanks a bunch friend!\n\nBINGO!", objectives = "Find the battle pets based on the riddles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84470] = { id = 84470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dirt-Caked Celebration Crate", description = "<Though unearthed and dusted off, this crate still smells of death. Regardless, Alyx would likely appreciate the supplies returned.>", progress = "Yes?", completion = "Oh, you found a missing crate! Wonderful!\n\nI really appreciate you returning these. If you find any more, please bring them to me.", objectives = "Return the Dirt-Caked Celebration Crate to Alyx.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84485] = { id = 84485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renowned with the Tazaveshi Brokers", description = "Well hey there!\n\nWe want to thank you for all your help. How about you meet me in Loamm, so we get you something nice?\n\nKeep up the good work!", sourceObjective = "Speak with Mimuup  in Loamm.", sourceObjectiveStatus = "unverified-source-field" }
quests[84489] = { id = 84489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shopping Squee!", description = "Now that you have an idea of some of the main attractions, let's talk shopping.\n\nThe main pavilion here contains just a few of places where you can look for amazing new purchases. Do a loop and talk to the shopkeeps to see what they have to offer.\n\nOnce you are done, come back and let me know if anything caught your fancy.\n\nTa-ta!", progress = "Don't be shy, you're allowed to browse. Go ahead and have a look at the wares for sale and then come back when you're done.", completion = "I hope you found something to your liking, or at the very least had fun browsing.\n\nYou know your way around, so now I turn you loose to go forth and enjoy yourself. This anniversary is for you, after all.", objectives = "Talk to the shopkeeps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84490] = { id = 84490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Vault", description = "Many of Dornogal's systems have been dormant for millennia and are now back online. One that you might find useful, {race}, is the Great Vault.\n\nOnce, this cache of armor and weapons would have supported the earthen in their Oathsworn duty to protect Dornogal. Now it is extended to you with the expectation that you use what you find there to aid others along your quest.\n\nThe Vault is housed here in Dornogal within the Council's Treasury. The Councilward has granted you full access to its contents.", progress = "The vault is yours to peruse, {name}.", completion = "So you've found some beneficial equipment within the vault, have you?\n\nGood. There are many more pieces stored within. Take a look regularly. You never know what you might find.", objectives = "Obtain a piece of loot from the Great Vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84506] = { id = 84506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pet Pursuit", description = "Hello, adventurer!\n\nI spotted a group of battle pet tamers who were going on about a bingo game. Jepetto Joybuzz was among them and seemed to be in some distress over his progress.\n\nWhy don't you see if he could use some help?", completion = "Oh, are you looking to help me track down some rare critters?", objectives = "Find Jepetto Joybuzz near the pet playground.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84519] = { id = 84519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Curiosity: Combat", description = "<You hold the relic and discover a shimmering glow emanating from it. This looks important. The Explorers' League would be interested in this.>", objectives = "Use and equip the Unbreakable Iron Idol to Brann Bronzebeard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84520] = { id = 84520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Curiosity: Utility", description = "<You hold the relic and discover a shimmering glow emanating from it. This looks important. The Explorers' League would be interested in this.>", objectives = "Use and equip Streamlined Relic to Brann Bronzebeard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84521] = { id = 84521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thoughtful Pursuits", description = "Maru has been such a good junior sleuth that it's time to reward her with a Thinking Cap of her own!\n\nI can't just hand one over to her, though, so I've buried the parts she'll need to make one herself. I've hidden the coordinates for each part in riddles. Figure out the riddles to find the hiding places!\n\nWould you escort her to make sure she doesn't run into trouble? You can use my Thinking Cap to help. Also, I'll give you a special clue book that will reveal riddles as you progress.", progress = "How's it coming along? Maru isn't giving you any trouble, is she?", completion = "You did it! And look at that big toothy grin on Maru's face. Thank you so much for helping.", objectives = "Escort Maru through Benatauk's  puzzle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84542] = { id = 84542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Radiant Echo", description = "<Within your hand, you hold a small Azerite sphere. Its light is steady and bright, but the sound it emits is plaintive and longing. It tugs at you, ever so slightly.>", completion = "<As you release the Radiant Echo, visions of the past materialize before your eyes. The Worldsoul herself is sharing her memories with you.>", objectives = "Bring the Radiant Echo to a Worldsoul Memory, then release it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84547] = { id = 84547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redemption Guaranteed", description = "<Even an empty Kaja'Cola can still has value. Perhaps Blinky Greasefingers might want it.>", completion = "I don't recycle these. I just refill them with off-brand cola.\n\nNobody can tell the difference, I promise!", objectives = "Deliver the Empty Kaja'Cola to Blinky Greasefingers at Flotsam Shoal.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84559] = { id = 84559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carved Crests", objectives = "The Arathi truly appreciate all your help in this dangerous land. Please accept this symbol of our gratitude.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84563] = { id = 84563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Toy Trouble", description = "Adventurer, Maru is once again in need of your aid.\n\nShe has an urgent matter that she would like to discuss with you.", completion = "Yaay you're here to halp!", objectives = "Speak with Maru.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84564] = { id = 84564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", objectives = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
