quests[84581] = { id = 84581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", objectives = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84582] = { id = 84582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", objectives = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84583] = { id = 84583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hozen On My Back", description = "Hello, {name}. I don't suppose I could trouble you again? A strange couple has been causing trouble near the edge of the petting area.\n\nPerhaps you could convince the hozen to stop shouting at our guests.", completion = "Riko's had it up to here with these horkin' wikkets!\n\nWhat the ook do you want?", objectives = "Confront the boisterous hozen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84588] = { id = 84588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation Toy Rescue", description = "Nooo! A sneaky thief has taken some of my friends' toys!\n\nYou're a good sleufer now, right? Can you halp my friend Yennu find his stolen toy? You'll find him on the Dragon Isles.", progress = "Did you find da toys?", completion = "Wow you're an expert toy rescuer! Who do you fink stole da toys in the first place?\n\nWe should go through da clues you found and see if we can figure out the culprit! Come back tomorrow and we can go over da evidence.", objectives = "Find the missing toys.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84595] = { id = 84595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Case of the Fur-Getting Wikket", description = "Riko has had enough of these blikkety tik-digglers! All Kiryn wants is to be a furry-haver, and these mankers won't give any!\n\nKiryn says Riko needs to stop jabberings. Says taking their furries is \"stealing.\"\n\nYou a helpful wikket? Find Kiryn a furry friend! Better take notes so wikket don't get stuck.", progress = "If wikket can't find a furry, Riko will have to be a stickypaw.", completion = "You really horkin' did it! You da best, wikket!", objectives = "Find a companion pet for Riko and Kiryn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84616] = { id = 84616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Celebrate Good Fun!", description = "Welcome to the Bronze Celebration! \n\nWe invite you to enjoy our myriad of events. You might choose to mirror your pet and run around our playground. \n\nYou could participate in one of our big events like Fashion Frenzy or Mount Mania. A different event begins every 15 minutes. \n\nOr you might fancy yourself a challenge. If so seek out Chromie as she cleans up her Codex to prepare for her tours. \n\nAny event will do, as long as you are having fun!", progress = "Are you enjoying our fine celebration?", completion = "It is fulfilling to see so many denizens of Azeroth and beyond visiting our celebration. It is in remembering all our pasts that we are able to come together and celebrate. \n\nWe hope that you will continue to enjoy our event. To assist you in your own adventures, take this boon of the bronze flight!", objectives = "Participate in activities around the celebration and tasks put forward by those visiting.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84619] = { id = 84619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ooker Dooker Literature Club", description = "The hozen in the Bilge Rat crew are master scavengers. For years, they've been visiting this island, snatching up anything that might be of value.\n\nAmong their spoils are many research materials that could help unlock the history of this place.\n\nInfiltrate their camp, board their ships, and recover whatever books, scrolls, and documents you can find.", progress = "Did you find anything worth reading?", completion = "What a fascinating collection of writings! I daresay I shall be up all night reading these.", objectives = "Acquire various writing from the Bilge Rat ships and landing area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84621] = { id = 84621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Squire's Spurs", description = "You come to Campalot to pledge fealty? Become Knight of the Brown Table?\n\nNot have look of tenderfoot, but even bravest knight start as squire. Earn spurs. Learn humility.\n\nProve you have learned it in same way. See what can do to help around castle.\n\nMight be good example to other squires, too.", progress = "Hmm, think missed spot.", completion = "Job good, Squire {name}. Remember lesson in humility.", objectives = "Help out around Campalot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84624] = { id = 84624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sandy Celebration Crate", description = "<This crate has certainly been on a journey! Alyx would appreciate the supplies returned.>", progress = "Yes?", completion = "Oh, you found a missing crate! Wonderful!\n\nI really appreciate you returning these. If you find any more, please bring them to me.", objectives = "Return the Sandy Celebration Crate to Alyx.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84625] = { id = 84625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surprisingly Pristine Celebration Crate", description = "<You found this crate of celebration supplies in the unmarked grave where you buried the bones in their place. Alyx would appreciate the supplies returned.>", progress = "Yes?", completion = "Oh, you found a missing crate! Wonderful!\n\nI really appreciate you returning these. If you find any more, please bring them to me.", objectives = "Return the Surprisingly Pristine Celebration Crate to Alyx.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84627] = { id = 84627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Three Heads of the Deep", description = "The reach of these creatures is truly frightening!\n\nI have encountered them countless times in the Imperial waters. I know their strategies well, and I have a plan to deal with them.\n\nMy scouts have pinpointed the location of three of their leaders. Eliminate them, and we'll seize the advantage.", progress = "Have you eliminated their leaders?", completion = "Excellent work, {name}. I could use someone of your caliber aboard my ship--should you ever be looking for work.", objectives = "Eliminate Warlord Thresh, Extractor Silsai, and Nereu of the Silent Wave", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84638] = { id = 84638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble in the Highlands", description = "Both Geya'rah and Danath have received word of unrest in the Arathi Highlands--civil unrest in Stromgarde, and raids on Mag'har and Stromic outposts.\n\nDanath and Geya'rah are returning to their homes, Stromgarde and Hammerfall, to defuse tensions.\n\nI asked to accompany them. I have long wanted to reconnect myself and my people to the Arathi. I also want to learn more about the Horde.\n\nGeya'rah was willing, but... Danath took some convincing.\n\nThough, I may have implied you were joining me...", completion = "I had been sent word of bandits roaming the Highlands but... I did not know it was this bad.\n\nIt's just as well we happened into this attack.\n\nIf we want to get to the bottom of this, we might as well start here.\n\nThough... I do wish Faerin were not here to see this.", objectives = "Travel to the Arathi Highlands via the portal in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84639] = { id = 84639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torches and Tar", description = "We've been attacked before. But this time... \n\n<Walker shudders.>\n\nThis was different.\n\nThey didn't want livestock, grain, or money. They took torches and some barrels of tar we use to fix our roofs.\n\nI don't know what they're going to do with it, but... I can guess. They're going to burn something down.\n\nYou need to stop them before they do another homestead harm!", progress = "I hope whatever they're planning doesn't involve my neighbors. Or Stromgarde!", completion = "Thank you, {name}.\n\nHopefully this \"snuffs out\" what they were planning.", objectives = "Retrieve 10 Stolen Torches from Defias bandits and 10 Barrels of Tar from Newstead Farm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84640] = { id = 84640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emblematic of Things to Come", description = "<This Defias bandit was carrying a badge with an unfamiliar emblem.\n\nThe emblem looks like a rising sun with long rays emanating from it. The sun and rays are colored red.\n\nPerhaps Danath can identify it.>", completion = "I don't recognize this emblem. And a Defias had it on their person?\n\nHm. Curious.\n\n<Danath turns it over in his battle-scarred hand, frowning.>\n\nI wonder what it means?", objectives = "Bring the Unfamiliar Emblem to Danath Trollbane at Newstead Farm.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84641] = { id = 84641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ill Tidings", description = "A Defias attack. The theft of tar and torches. A group called the Red Dawn recruiting here in the heart of the Highlands...\n\nStromgarde was right to send a missive asking for my return. What is going on here?\n\nI placed Colonel Nials in charge after Marran's foolishness led to her imprisonment. I must head to Stromgarde and speak with Nials immediately.", completion = "This is much worse than I thought. With the attacks disrupting supply lines, the people are angry, hungry, and looking for someone to blame. The easy choice is blaming our neighbors at Hammerfall.\n\nWe cannot let this unrest continue. I must speak to Nials and my advisors.\n\nI see Faerin has volunteered the both of you to help the people of Stromgarde. I do not like putting either of you to work on what is a diplomatic mission, but helping Brewston while I speak to Nials would put my mind at ease.", objectives = "Meet Danath Trollbane at the gates of Stromgarde Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84643] = { id = 84643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curfew Kerfuffle", description = "I'm glad for your help. Between deployments to Khaz Algar, responding to threats in the Highlands, and desertion, we simply don't have enough soldiers to enforce order.\n\nMarran's supporters are causing trouble throughout the city. They're stealing supplies, harassing people--you name it. We've enacted a curfew, but Marran's supporters are openly defying it.\n\nAs my deputies, go around and tell the troublemakers to go home. If they get rowdy, you have my permission to teach them a lesson.", progress = "I understand that curfews are unpopular, but we really need one right now.", completion = "It's despicable really. They try to intimidate loyal citizens and make them leave just because they aren't human. They also shout down anyone that doesn't agree with them.\n\nMany around here just try to avoid them, but it seems like they hang out where it's hard to do that.", objectives = "Deal with 15 Marran Supporters in Stromgarde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84645] = { id = 84645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deputy Delivery", description = "Trade in Stromgarde has broken down. We're short on goods and workers because of the attacks.\n\nNials was too busy, so I took it upon myself to write official requests for aid.\n\nMost are simple and straightforward--writs for supplies and such for the Stromic army.\n\nThe desist writ for Joseph is different. He is loudly blaming everyone not human for our woes. Someone needs to officially tell him to shut his yap before he starts a riot.\n\nAs my deputies, would you enforce my requests for aid?", progress = "I know some won't be happy with what we're requesting of them, but it's what's best for Stromgarde and its people.", completion = "You have my thanks and the thanks of Stromgarde.\n\nI'm sorry you got an earful from Joseph--at least he left peacefully!\n\nDespite how it may seem, the city is still loyal to Lord Trollbane. Mostly.\n\nLady Marran's followers are just louder. And angrier.", objectives = "Deliver Brewston's request writs to people in Stromgarde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84649] = { id = 84649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marran Trollbane", description = "I am Colonel Veronica Nials, and I am in command of Stromgarde in Lord Trollbane's absence.\n\nI'm sure while aiding our people you've heard the name \"Marran\" in Stromgarde. Lady Marran Trollbane is Danath's niece. She was briefly regent while Lord Danath Trollbane campaigned for troops for Khaz Algar. \n\nHer actions during his absence led him to imprison her when he returned.\n\nThat said, Lord Trollbane felt Faerin should speak to her. Perhaps to get... perspective. I can take you to her if you wish.", completion = "Marran may be in prison now, but her supporters continue to spread her rhetoric across the Highlands.\n\nWhatever she may say, I do not believe that she is the leader of this \"Red Dawn\" that you both are speaking of.\n\nI see who comes and goes. She receives no outside visitors.", objectives = "Observe the meeting between Faerin Lothar and Marran Trollbane in the barracks of Stromgarde Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84650] = { id = 84650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding Refuge at Refuge Pointe", description = "If you want to find Lord Trollbane and tell him your theory about Lady Marran, the missive called him to Hammerfall, far to the east of here.\n\nHe may have stopped at Refuge Pointe on the way--it's a Stromic encampment about halfway to the orc town. Because of the frequent bandit attacks in the area, I believe he meant to stop and check in with our people there.\n\nYou might catch up with him there.", progress = "It's good to see humans and orcs banding together to help one another.\n\nIf only the Arathi here could have seen what I did at Khaz Algar.", completion = "Another bandit attack? And they carry the same emblem as the bandits at Newstead?\n\nIf this is connected to the Red Dawn and Marran...", objectives = "Look for Danath at Refuge Pointe in the Arathi Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84651] = { id = 84651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Familiar Face", description = "Early on, these attacks on our settlements seemed to be pockets of bandits competing for resources.\n\nNow they are better coordinated. As if they are working together as a group. \n\nThat's bad news for everyone.\n\nBut rivals don't come together without a strong leader. And without them, they will fall.\n\nIf you're willing, find the leader of this attack on Refuge Pointe and eliminate them.", progress = "Go. I will protect these people until your return.", completion = "He escaped?\n\n<Karga spits on the ground.>", objectives = "Defeat the leader of the attack on Refuge Pointe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84652] = { id = 84652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supply Run", description = "Stromgarde's troops are in Khaz Algar and it cannot protect its outlying settlements. \n\nHammerfall does what it can to help, but we too fight in Khaz Algar.\n\nWe've taken many injured Stromic refugees to Hammerfall, but feeding them all has strained our resources.\n\nBut there may be a way to help more people.\n\nVikki told me Refuge Pointe is a supply depot for nearby settlements. If we can get our hands on some supplies, we can care for more refugees in Hammerfall.", completion = "Good, {name}. \n\nI hope Stromgarde does not mind us \"borrowing\" these supplies for their refugees.\n\nHeh.", objectives = "Collect 4 Supply Crates from Refuge Pointe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84656] = { id = 84656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onward to Hammerfall", description = "First an attack on Newstead Farm by Defias, now an attack on Refuge Pointe by these Scarlet Crusaders. \n\nDifferent groups of bandits, but both speak of this \"Red Dawn\" and carry the same emblem. \n\nAlso, Joseph is directly involved.\n\nThis all seems connected... and it leads back to Marran.\n\nDanath needs to know what's going on. If he's not here, he should already be at Hammerfall. \n\nWe should head there as soon as possible.", completion = "If Danath is not here... Where is he?", objectives = "Meet Faerin Lothar at Hammerfall in the Arathi Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84657] = { id = 84657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Stromgarde", description = "Eitrigg was right. The Red Dawn are trying to start a conflict between the Horde and the Alliance.\n\nWe need to get back to Stromgarde and tell Colonel Nials that Danath has been kidnapped. She will surely commit all her resources to a search!\n\nCome, {name}. There's no time to waste!", completion = "<Brewston leans in close to you and speaks just above a whisper.>\n\nI'm glad I found you. I need all the allies I can get.\n\nYou're very lucky they left you alive.", objectives = "Return to Stromgarde and enlist Colonel Nials's aid in finding Danath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84658] = { id = 84658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding Family", description = "Where's my mama? My papa?\n\nEllie?\n\n<Maggie looks around with tears in her eyes.>\n\nI was followin' Mr. Gresham and Clarabelle when we saw the bandits. He grabbed me up and we ran here.\n\nI don't know where Mama and Papa and Ellie are.\n\nCan you find them for us? Clarabelle is starting to get worried...\n\n<Maggie sniffles.>", progress = "Ellie must be so scared!", completion = "You found them! You found them! Thank you so much!\n\n<Maggie hugs Ellie tightly.>", objectives = "Discover the fates of Marshall Wiltshire, Sharon Wiltshire, and Ellie at Newstead Farm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84659] = { id = 84659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Search for Faerin", description = "I saw Faerin being taken away, but couldn't follow without them seeing me. She's probably being held in another building.\n\nGo find her. Hopefully, she's still alive...\n\nAnd see if you can find any more information on the Red Dawn. There's no way we should have been overwhelmed so quickly. Colonel Nials and Lady Trollbane must have installed their cronies everywhere.\n\nThe more information we have, the more we can use against them when we fight back.", progress = "Have you found Faerin?", completion = "I'm glad Faerin is all right. \n\nAnd this information you've found...\n\n<Brewston's shoulders slump.>\n\nWhen people are desperate, they'll believe in any promise of a better life no matter whom it's from.", objectives = "Search the structures in Stromgarde for Faerin and information on the Red Dawn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84664] = { id = 84664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making the Underworld Go Round", description = "Hey there, 'Overcrawler.' You're lookin' more than a little out of your element there. You get run over by an airship or something?\n\nWhatever. Doesn't matter. Take it from one outsider to another, if you're going to survive down here you're gonna need to learn the rules of the road. Gold's all well and good where you came from, but down here you're gonna need Kej, and lots of it.\n\nNow here. Consider this a token of good will from Lady Pedipalps up there. Go get yourself something nice.", progress = "What, you allergic to retail therapy or something? Get out there and live a little!", completion = "Get a good look around? This place is pretty spooky, even for a savvy gal like me. But get enough Kej together and you'll be able to buy all sorts of stuff, both here and in the City of Threads.\n\n<Linny looks you up and down.>\n\nThen again, you're probably still gonna get eaten, so maybe look into fine nerubian gravestones.", objectives = "Spend Kej at one of the vendors in the Weaver's Lair.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84667] = { id = 84667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The G.O.L.E.M. of Progress", description = "The citizens of Undermine cry out for help! They need protection! They need joy! They need to get by!\n\nAs an inventor, I've spent my life building somethin' that'll solve our people's problems, and it's just about ready for a test run. I'm calling it my Goblin Optimal Livability Enhancement Machine, or G.O.L.E.M. for short!\n\nFind some problems and take it out for a spin- and take my son with you! Pitz doesn't have an inventor's bone in his body, but certainly he can yak it up with the neighbors.", progress = "Pops is really over the moon about this G.O.L.E.M. thing. I hope it works out for him.", completion = "Well, it sure was great while it worked!", objectives = "Tour the Vatworks with the G.O.L.E.M. and solve problems for Gart Pocketz, \"Cranky\" Nan, and the children of Undermine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84671] = { id = 84671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest Wk" }
quests[84672] = { id = 84672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garbage Day", description = "My old man's got all these crazy ideas about helping the world... I dunno. It's all a bit over my head, but I guess that's why I was never the inventor he wanted me to be.\n\nStill, I've got some thoughts on how to solve problems around here. Like those dang rodents getting litter all over the streets!\n\nIt might not revitalize the spirit of the community or whatever, but I bet people would be happier if we cleaned up the streets.", progress = "Toxic fumes? Nah, that's just what Undermine smells like!", completion = "The place is looking cleaner already! Maybe there's something to this G.O.L.E.M. thing.", objectives = "Collect 12 pieces of litter and use the G.O.L.E.M.'s incinerator function to dispose of them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84673] = { id = 84673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "World's Okayest Inventor", description = "I'm... not the inventor my old man is. Or much of an inventor at all, really. My masterwork is over by the wall there, but to be honest, there's a lot of work that still needs to be done to get it to do... anything.\n\nBut this! This could be my big chance to prove to Pops that I've got what it takes to make him proud!\n\nAll we need to do is actually, uh, figure out how to repair this thing. How hard could it be?", progress = "Is it... working?", completion = "This isn't good. This isn't working at all.", objectives = "Help Pitz repair the G.O.L.E.M.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84674] = { id = 84674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The G.O.L.E.M. Goes Berserk!", description = "The G.O.L.E.M.'s gone berserk! Haywire! Bonkers!\n\nI gotta go chase it down--who knows what kinda trouble an invention that powerful could cause! Plus, imagine how mad my old man would be if we lost it!\n\nI hate to ask you to clean up my messes, but someone's gotta hang back and get everything in order again. Could you do that?", progress = "Pitz! Has anyone seen Pitz?", completion = "All this chaos... what has the G.O.L.E.M. wrought?!", objectives = "Calm the chaos caused by the G.O.L.E.M.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84675] = { id = 84675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Showdown in the Attic", description = "I've been so blind! Everything's falling apart!\n\nThe neighborhood is worse off than ever, and the G.O.L.E.M.'s to blame! And my boy, my dear Pitz...\n\nHe ran into this building to try and stop the contraption. I was so hard on him, and now I might never see him again...\n\nYou gotta find him. And stop that thing once and for all.", progress = "My hubris... that's the first thing they tell you in inventor school! Why didn't I listen!", completion = "Y'know... he may not be much of an inventor, but I'm proud of that boy.", objectives = "Rescue Pitz and destroy the G.O.L.E.M.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84680] = { id = 84680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rock 'n Stone Revival", description = "The attacking vrykul harness salt and brine elementals, turning them against their foes.\n\nTo counter their assault, we can harness them as well.\n\nUse this Rock Reviver to unleash the elementals residing within nearby stones, transforming them into powerful allies. With their help, we can defeat this vrykul threat.", progress = "Have you stopped the vrykul and their elemental thralls?", completion = "You've done well harnessing the elementals, {name}. I eagerly await further displays of your abilities.", objectives = "8 Restless Pebbles or Stones revived, 8 Bloodbrine horrors and the Bloodbrine Monstrosity defeated.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84682] = { id = 84682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Pacts and Patrons", description = "The Severed Threads is ready for you and your allies. You will be a lit torch to Ansurek's webs.\n\nThe General, the Vizier, and, myself, the Weaver, each have differing methods of combating our foes... and different benefits of aiding our accomplices. You may prefer to prioritize one, or perhaps to dabble with all three instead.\n\nMeet with our representatives, and inform yourself on our varying practices. Then you may forge your first Pact.\n\nDon't worry, little morsel, no choice is ever permanent.", progress = "Have you considered your options?", completion = "May your chosen patron favor you, as you have them.", objectives = "Speak with the representatives of the Severed Threads, then forge your first Pact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84683] = { id = 84683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Gutter", description = "What're you doing here? Sabotagin'?\n\nI can understand that. Things are way out of hand. But if we explode this pipe here, it'll get even worse. Black Blood everywhere. Maybe together we could come up with somethin' real to do.\n\nMeet me in Gutterville. We'll talk more, away from these awful slimes!", completion = "Keep yer voice down! I've never seen so many spies in Gutterville...", objectives = "Meet Pamsy in Gutterville.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84684] = { id = 84684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ratts' Race", description = "I saw a vulpera acting very suspicious. She seemed... on edge. I think I saw a knife at her side and a look of dark magic in her eyes.\n\nShe noticed me staring and immediately fled. Is she a wanted criminal?\n\nShe... dropped this. Here.", progress = "<Ratts seems to have dropped this gem in her haste.>", completion = "<What could be the purpose of this gem that Ratts left behind?>", objectives = "Track down Ratts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84693] = { id = 84693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weaver's Lair Profession Table", description = "Present this token to Ak'itaz in the Weaver's Lair to have your own personal profession table constructed.", completion = "What have you here? Ah! I make table for you. What do you like to build? \n\nDo you work with meat, metal or magic?", objectives = "Speak with Ak'itaz in the Weaver's Lair.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84700] = { id = 84700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pacts Below", description = "This weave-rat carries a note upon its body. It's addressed to you, from the Widow Arak'nai.\n\n\"Dearest morsel,\n \nMyself and the other members of our Severed Threads triumvirate request your presence. Azj-Kahet itself is on the precipice of an evolution, but we'll need your... unique methods if we're to see it through.\n\nAnd, as always, the rewards to you and your cause will be quite magnificent.\"", completion = "Thank you for making the trip back down to my humble lair.\n\n<A deep chuckle rumbles out from Widow Arak'nai.>\n\nWe have got grand plans in store for you. Certainly, certainly.", objectives = "Go to the Widow Arak'nai in the Weaver's Lair.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84701] = { id = 84701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Speaker", description = "So there is someone else who has experienced something close to what I experienced. Yet it is not the same.\n\nI must speak with him.", completion = "Have ye come tae say goodbye?", objectives = "Speak to Magni in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84704] = { id = 84704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Different Point of View", description = "Danath is not here. \n\nFaerin says he journeyed to Hammerfall because we requested a meeting. I sent no such message to him nor anyone else. \n\nI will dispatch outriders immediately to search for him. \n\nWhile we wait for their return... You and Karga's quick thinking may have saved our human refugees. We had just run out of food to give them.\n\nDistribute the crates directly to them. I'm sure they will be grateful for the food inside.", completion = "I never realized how much my people have in common with the orcs. We are both far from home, we are both self-sufficient, we are both peoples born into war...\n\nAnd most of all, their sense of duty and honor rivals ours.\n\nI feel... even more at home here than in Stromgarde.", objectives = "Place 4 Supply Crates next to Arathi Refugees taking shelter in Hammerfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84705] = { id = 84705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Withering the Witherbark", description = "The Witherbark have always been an annoyance since I have been here. But now?\n\nSomething has stoked their ire. They are attacking human settlements. Perhaps the Red Dawn is again to blame.\n\nEitrigg has ordered us to try to help the humans they attack. We have stepped up our patrols and welcomed refugees. \n\nBut we need someone to go to their village and bloody the Witherbark's noses. They're overconfident. They think they can get away with attacking our outriders!\n\nMake them think twice about that.", completion = "Feh.\n\nThat will surely cow them. I'd be surprised if I saw any of them stray from their village any time soon.", objectives = "Slay 15 Witherbark trolls at Witherbark Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84706] = { id = 84706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crime Family", description = "This Syndicate human came to us hoping to trade information for a rescue mission. The Syndicate is a recent thorn in our side, so I had half a mind to cut him down where he stood. \n\nBut he claims to have vital information, and with this news of Danath's disappearance... it might be worth the risk to do as he asks.\n\nHe has three brothers being held captive inside Witherbark Village. Go in, find them, and if they're alive, extract them.", completion = "Barclay is lucky you reached his brothers in time.", objectives = "Save Crestor, Holt, and Perry from the Witherbark trolls in Witherbark Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84707] = { id = 84707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To See a Troll", description = "There's no word from the outriders yet, but Eitrigg has not told Geya'rah of Danath's disappearance. \n\nI have told him we would go and give her the news.\n\nShe's at Go'Shek Farm dealing with a Witherbark troll attack. Eitrigg says they've become increasingly aggressive recently. \n\nI can't help but think of the history there--of the Troll Wars and Arathi battles. But I admit I see them differently now after learning more about the Horde.\n\nLet's go. We can look for Danath while we're out there.", completion = "Faerin has informed me of Danath's disappearance. While that is... troubling... We can't return to Hammerfall just yet.", objectives = "Meet Overlord Geya'rah at Go'Shek Farm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84708] = { id = 84708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Syndicate Strikes Back", description = "This human is claiming the Syndicate scum are going to attack Hammerfall! Another day I would not be concerned. But with the outriders dealing with the Witherbark and searching for Danath, Hammerfall is undefended!\n\nLet's go {name}. We must defend our home!", completion = "I should have been here. I could have done something.\n\n<White-hot fury and rage emanate from Geya'rah's tense posture and tightly-closed fists.>", objectives = "Meet Overlord Geya'rah at Hammerfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84709] = { id = 84709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammerfall Down", description = "<Eitrigg growls in frustration.>\n\nI was such a fool!\n\nI should not have sent away those outriders. Without them, the Syndicate have overrun Hammerfall.\n\nAnd were it not for my fool heart... The \"refugees\" turned out to be Syndicate spies, curse their greasy hides...\n\nBut now you're here. Now, we can force the Syndicate out. Eliminate their soldiers and save any trapped civilians. \n\nThose spies have had enough of my open hand. Now they'll suffer my fists!", progress = "The Syndicate...\n\nI haven't seen them in this number in many years.", completion = "There are still Syndicate stragglers about, but Hammerfall once again belongs to the Horde!", objectives = "Eliminate Syndicate soldiers and save trapped civilians in Hammerfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84710] = { id = 84710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Once Bitten Twice Shy", description = "I caught a glimpse of who was leading the attack.\n\nIt looks like Joseph the Enlightened may be less full of hot air than we thought he was.\n\nIs he now part of the Syndicate? I thought he was part of the \"Crusade.\" I suppose it doesn't matter. If we want to stop the attack, we'll have to take him out.", progress = "I fully expect him to run away again like the coward he is.", completion = "Joseph escaped again, and this time his warning was much more foreboding. He has darkness in his mind... and his soul. \n\nI am... confused how he can profess to follow the Light.", objectives = "Defeat Joseph the Enlightened in Hammerfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84711] = { id = 84711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Danath's Disappearance", description = "My outriders discovered a destroyed caravan on the road. \n\nAround it were the bodies of Stromic soldiers.\n\nIt could be Danath's escort. Or it could be another hapless group.\n\nEither way, we must investigate. Let us hope Danath is not among the dead.", completion = "This wasn't a battle. It was an ambush and a massacre.", objectives = "Meet Overlord Geya'rah at the Arathi Highlands crossroads.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84712] = { id = 84712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "False Flag", description = "This was not done by simple bandits. This spot was chosen specifically for an ambush. And these troops were taken down quickly and efficiently.\n\nIf Danath was heading to Hammerfall, this road is the most direct route. That makes it predictable.\n\n<Geya'rah grimaces.>\n\nWe must search for Danath among the dead and find out what happened here. Leave no stone left unturned.", completion = "It is decided then. \n\nIf we are to prevent war, we must alert the Alliance to the situation and rescue Danath as quickly as possible.", objectives = "Investigate the area for clues as to Danath's disappearance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84713] = { id = 84713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallen Fortress", completion = "I believe we've found where the Red Dawn were hiding.", objectives = "Meet Eitrigg at Ar'gorok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84714] = { id = 84714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From Ironforge With Love", description = "This \"Red Dawn\" is occupying the fortress of Ar'gorok. Bandits of all types and bands have taken refuge here under their banner.\n\nAnd I'm sure they've brought their spoils with them.\n\nIt may help calm tensions if we recover the goods they've stolen and return them to their rightful owners in the Arathi Highlands.\n\nSee if they are carrying anything with them.", progress = "Who knows what we will find.\n\nWhat they've stolen could have come from here in the Arathi Highlands, or as far as the Horde or Alliance capitals.", completion = "More supplies? Good.\n\nHm. Looks like these were on their way from Ironforge to Stromgarde.\n\nFrom what Faerin has told me, the Stromic will be very pleased that we found them.", objectives = "Collect 20 Stolen Ironforge Supplies from Red Dawn troops within Ar'gorok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84715] = { id = 84715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Search for Danath", description = "Using Ar'gorok as a base was clever. Very clever.\n\nIt looks like the bulk of their forces are here. If Danath is alive, I'm certain they would keep him here.\n\nSearch the buildings for him. And look for any information on this Red Dawn that you can. Anything might be helpful in taking them down. \n\nLet's hope Danath is alive. If he isn't, a long and bloody conflict is ahead of us.", progress = "Danath is here but we need a key to open the door!", completion = "You found a key? \n\nJust what we need.", objectives = "Search the structures in Ar'gorok for Danath and information on the Red Dawn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84716] = { id = 84716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Returning to Stromgarde", description = "While feigning sleep, I heard the guards brag about the Red Dawn's plans for Stromgarde.\n\nMy kidnapping was just the start.\n\nColonel Nials--after all these years! She will be the one to turn the key and free Marran, my niece, to do as she wishes and start a coup!\n\nMarran will lead Stromgarde's army and the Red Dawn to Hammerfall to secure the Highlands for \"Strom.\"\n\n<Danath's face is red with fury, but his eyes water with tears.>\n\nWe must gather our allies... and confront these traitors!", completion = "Marran has made her move. The coup has started.\n\nFaerin and Brewston have rallied the Stromgarde loyalists, but there are many Marran supporters.\n\nThis will be a bloody civil war.", objectives = "Meet your allies at Stromgarde Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84717] = { id = 84717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise of the Red Dawn", description = "Danath and Eitrigg ran ahead to confront Marran. They hope if they stop her, they can end the coup--and the bloodshed.\n\nBut after seeing Joseph the Enlightened's handiwork first hand... \n\nDespite how unorthodox he may be, he's still a danger. And I hate to say it, but I would relish the chance to finally take that underhanded cretin down.\n\nHe's blocking our path up ahead at city hall. Let's take him down and then help Danath and Eitrigg end this war.", completion = "Marran was given mercy.\n\nI'm still not sure she deserved it.\n\nBut there is little she can do now without her name and title. After failing twice, the Stromic will not follow her. And without the power her name and title wielded, she's useless to the bandits.\n\nMercy or not, I thank the Light that the conflict has been ended.\n\nYou have my thanks as well, {name}.", objectives = "Defeat Joseph the Enlightened and help Danath and Eitrigg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84719] = { id = 84719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Expedition Awaits", description = "Greetings, {name}! Are you here to answer the Siren Isle's call to adventure?\n\nRecently, a goblin salvage team discovered an isle with a strange \"singing crystal\" at its center.\n\nLike the goblins, the Arathi of Hallowfall have taken a keen interest in this crystal--as have we. We've been preparing an expedition to the isle!\n\nMost of the expedition has gone ahead, but the goblins last vessel is set to leave momentarily.\n\nIf you hurry, you can catch them before they leave and join us!", completion = "Ah, so you're the one Dawn convinced to join us, eh? \n\nWell, hurry up! They've been adamant about getting us a proper Stormrider-ranger-whatever escort out of the city, but it's takin' too long!\n\nThe Arathi and other earthen are already on the Isle and Ricket is probably wonderin' where the heck we are!\n\nC'mon! I can give you the deets on the way!", objectives = "Meet Skaggit by the East Gate of Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84720] = { id = 84720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Siren Isle!", description = "The Siren Isle is a myst'ry. A potentially profitable one.\n\nMy crew thought they hit it big when they found a deserted island with some strange, singin' crystal...\n\nTurns out, everyone in Dornogal is interested in unclaimed \"strange singin' crystals.\" Both the Arathi and earthen scrambled quick an' were off before we could even charter a zeppelin!\n\nFortunately for us, Ricket and crew have gone ahead to set up.\n\nWe're the last to depart, an' I'm itchin' to go. What're we waitin' on?", completion = "We made it safe and sound!\n\nRicket says the whole camp's still buzzin' about the crystal.\n\nSeems like everyone's got different ideas on how to go about figurin' out what to do with it.\n\nThey didn't like Ricket and I's way but, you might be better at diplomacy.\n\nYou wanna get involved?", objectives = "Speak with Skaggit to journey to the Siren Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84721] = { id = 84721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Scan a Crystal", description = "In order to understand the \"singing crystal\" at the heart of the island, we will need some special machinery.\n\nWe have forged a device to scan its exposed facets, but the crystal's energies are far too complex to read. It has a highly unusual energy signature.\n\nThe goblins and Arathi seem keen to contribute, so let us proceed with their help.\n\nTake my toolbox and retrieve the prototype and the components the Arathi and goblins have prepared.", progress = "Normally, our technology is quite capable when it comes to crystals and the energies found within them. \n\nBut the energies found here are anomalous and don't synchronize with our technology...", completion = "Skepticism... disengaged. \n\nIt would seem the radiant remnants from Hallowfall harmonize perfectly with the energies found here, giving us a proper signature to latch onto.\n\nThe goblins' batteries are... more than we need, but they appear to be doing the job effectively.\n\nWe're almost ready for the field test!", objectives = "Assist Bargus by collecting the earthen prototype, the Arathi's focus and the goblin's power source.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84722] = { id = 84722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Facet-nating Signals", description = "Intriguing! \n\nThese radiant remnants from the Arathi seemed to have given our device the necessary focus it needed. All that remains is to attune it properly to its size.\n\nIn order to attune to the signal, we'll need to set up some pylons around the site.\n\nThere is testing to initiate, {name}. Follow me if you would like to assist me.", progress = "Once the pylons are operational, I should be able to triangulate the signal.", completion = "Fascinating!\n\nThe pylons' attunement indicates this crystal is far larger than this facet would suggest. \n\nAccording to the complexity of the signature, it appears to stretch for miles beneath our feet and--wait, what is this?\n\nA second signature appears to be originating from over the hill? Curious indeed...", objectives = "Meet Bargus by the Crystal and help him set up the pylons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84723] = { id = 84723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buried Secrets", description = "These ruins are... quite old. Well, old by most outlanders' standards.\n\nWhich begs the question: was finding this chamber the unfriendly outlanders' directive, or was it finding the tablet?\n\nOne clue is that my readings suggest energy is flowing through the tablet as a conduit rather than originating from it.\n\nShall we take a closer look?\n\nPerhaps investigation will yield some answers--and the source of the energy readings.", completion = "By the forge... this is...\n\n<Bargus stares wide-eyed in wonder at the gleaming crystal, struggling to find words. After a moment, he nods.>\n\nThis is most certainly the source of the second signature, though the energies here appear to have fused with the original.\n\nIt's almost like it wanted us to find this place...", objectives = "Investigate the ruins and find the source of the signal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84724] = { id = 84724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Radiant Vault", description = "This vault... this crystal...\n\nWho made this place? Who lived here? And who is this \"Cyrce\" we keep seeing mentioned on the tablets?\n\nWhen we set off to learn about the crystal, I did not anticipate discovering the remnants of an ancient civilization far beneath the earth.\n\n<Bargus ruffles his wiry moustache before glancing at you.>\n\nThis bears closer examination, don't you think?", progress = "It would seem we've made quite the discovery...", completion = "More queries and very few answers.\n\nFortunately, the device was able to gather some data from the energy readings. \n\nIt will take time to process, but we will soon have a better understanding of this \"Siren Crystal.\"\n\nIn the meantime, let's take a closer look at that ring and citrine shard you found. Angorla here will be able to help.", objectives = "Investigate the Crystal Shrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84725] = { id = 84725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Circlet Calls", description = "<Angorla peers at you from over her spectacles with excitement.>\n\nCan you hear it, {name}?\n\nThis small, humble citrine is calling out to the circlet... just as the Siren Crystal called out to you and to all of us.\n\nI am uncertain what will happen when you reunify them... but there's only one way to find out.\n\nPlace the circlet upon your finger and socket the citrine into the setting.", progress = "Have you placed the citrine into the circlet, {name}?", completion = "I can feel it from here... radiating. Thrumming with a long-dormant power.\n\nWho carved these small little citrines? Why do they appear to fit perfectly into the Circlet yet... they were found separated?\n\nOh, how I wish I had seen what you and Bargus had found within the Vault...", objectives = "Equip Cyrce's Circlet and socket the Windsinger's Runed Citrine into the Singing Wind Socket.\n\nThen, remove the Windsinger's Runed Citrine from the socket.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84726] = { id = 84726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uncovered Mysteries", description = "<Angorla takes your hand in hers and examines the crystal-embedded circlet closely.>\n\nCan you feel the energy humming through it, {name}? The circlet feels... awake. \n\nPerhaps more secrets lie around the isle, waiting for you to uncover them.\n\nDawn encouraged us to explore and learn about this isle, but I've got my work cut out for me here.\n\nWhy don't you see what other secrets you can find?", progress = "What have you found? Another treasure, perhaps?", completion = "Curious. Even as fragments, the pieces hum with energy. I wonder if I...\n\n<Angorla presses the fragments together like a puzzle, squeezing them in her palm. After a moment, she opens her hand and reveals a neatly-fused shard.>\n\nIt may be less intricately-carved or ornate as the citrine you found in the vault, but there is power here, even in a small stone like this.", objectives = "Uncover hidden secrets around the Siren Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84727] = { id = 84727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Second Signal", description = "An unexpected development.\n\nThe energy signature appears to have a secondary source--and it is just north of here.\n\nCuriosity activated.\n\nJudging from the estimated size of the crystal, I theorize it might be a secondary exposed facet.\n\nFurther investigation is required. Follow me.", completion = "It would seem we are not alone on this island after all, {name}.\n\n\n\nTo initiate violence before diplomatic engagement... An illogical provocation that yielded unfortunate consequences.", objectives = "Follow Bargus north.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84728] = { id = 84728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reforged Anew", description = "The cracked citrine you found seems to be a perfect fit for one of the sockets found in the ring, yet...\n\n<As Angorla sockets the shard into the ring, the citrine wiggles loose and pops out.>\n\nThe ring appears to be rejecting the piece. If we can repair the citrine and stabilize the energy within the shard, perhaps the ring will accept it?\n\nSince you've been so helpful with Bargus, care to lend another hand?", progress = "A fractured citrine is hardly an obstacle!", completion = "<Angorla holds the glowing citrine in her hand before holding it out to you.>\n\nThat seemed to do the trick... I've never felt such energy radiate from such a small crystal before. \n\nThe runes engraved on it are quite ancient and very powerful.", objectives = "Help Angorla repair the Citrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84730] = { id = 84730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Armored Charge", description = "The inorganic material of this island is peculiar. The effects of salt water and years of storm erosion have enriched the minerals of this place.\n\nAnd enriched minerals are exactly the type of material an Ordinant seeks to infuse into new armaments.\n\nBring me a considerable amount of storm-flecked debris from the isle's myriad of creatures. I would like to see if they are suitable for my craft.", progress = "Have you found any storm-flecked debris? It should be somewhat plentiful here if you're willing to look.", completion = "<Bargus crushes a chunk of debris in his hand and spreads it on his anvil to examine.>\n\nFascinating... this detritus contains slivers of crystalline material. I wonder if it is eroded fragments of the Siren Crystal...\n\nI may have another task for you, {name}.\n\nBut first, help yourself to the armaments I've forged.", objectives = "Collect 50 storm-flecked debris.\n\nDebris can be looted from creatures across the Siren Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84731] = { id = 84731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Storm Breadcrumb" }
quests[84735] = { id = 84735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Truth of the Dark Irons", description = "Few know the truth of the Dark Iron clan. Even fewer have seen it for themselves.\n\nThe Timewalkers have agreed to take us back. They will send us to the time when our clan lost its emperor. And in doing so, I hope I can show you everything that came from that defeat. The good. The bad...\n\nWill you see the truth for yourself?", progress = "I will guide you along your path. Though the end of it... I don't know if I can bear to witness that again, champion.", completion = "The Dark Iron clan was lost to Ragnaros. I dreamed of freeing them from his thrall. If only I could have done so before my husband was...\n\nHere. Take these tokens from our hosts. And thank you for seeing the truth with your own eyes.", objectives = "Defeat Emperor Dagran Thaurissan in the Return to Blackrock Depths raid.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84740] = { id = 84740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bridge to Nowhere", description = "Are you heading to the dunes? I'm looking for my sister, Shahata. I don't know if she's alive, but I have to find her.\n\nThe only place I can think to start the search is our village. K'aresh is nothing like I remember. I need landmarks--anything I can recognize to navigate by.\n\nTake this echo surveyor. It will reveal traces of the past--hopefully enough for me to orient us.", completion = "Thank you, {name}. I think I have my bearings now. You see how much life used to be here? It's hard to imagine Shahata surviving here for so long... No. We'll find her. We have to.", objectives = "Use the Echo Surveyor to help Om'fennad find his way.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84741] = { id = 84741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signs in the Sands", description = "Things are starting to feel familiar. I think I know the way back to my village.\n\nI should tell you... I'm not just looking for my sister. Our mother died when I was studying in the cities. Shahata buried her under her favorite tree, but I wasn't there. I swore I would come home to conduct the funeral rites, but I didn't make it in time.\n\nI have left my oath unfulfilled for far too long. I owe it to mother to at least try now. Come--let's search the village.", progress = "This can't be it! There must be something left.", completion = "I don't know what I expected. She's right. I did break my oath, and now the village is gone.... She's still here, though. \n\nIf she has anything that belonged to our mother, then there's still a chance the surveyor can trace it to the grave.", objectives = "Follow Om'fennad to his village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84755] = { id = 84755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Toy", description = "Maru discovered that one of her toys is now missing!\n\nCould this be related to the other missing toys that you previously helped her friends with?", completion = "Nooo! My toy is gone!", objectives = "Speak with Maru.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84756] = { id = 84756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Toy Thief", description = "My toy! It's been stolen!\n\nWe have to figure out da culprit before they take more toys!", progress = "Did you find my toy?", completion = "Yay! You found ALL the toys! How did dat big doggo collect so many?\n\nI'll have to go see if anymore of my toys are in da pile...\n\nThanks for all the halp.", objectives = "Discover the toy thief.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84759] = { id = 84759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ill-met in Starlight", description = "I used to practice what I would say when I saw my brother again. Then I stopped believing I would...\n\nHe's been away all this time, and now he comes to ask for heirlooms? I dug our mother's grave beside her favorite tree. Alone. He should have come back then, I don't have time to help him ease his conscience now.\n\nIf you two are so set on talking, at least have the sense not to do it in the open. Come to my camp--we'll speak there.", completion = "I hadn't expected to see Fennad again. He's a bit late to help with mother's funeral rites. The tree is gone along with the grave, and now he comes to ask for favors?", objectives = "Meet Shahata at her camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84760] = { id = 84760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Friendly Warning", description = "Before the Devouring, the Sufaadi were priests. There were customs of courtesy and charity. Those were erased with the rest of K'aresh. If the Wastelanders think I won't retaliate, they'll never stop targeting me.\n\nI think you understand the value of a show of force. Kill their leaders--let it be a warning for the others.", progress = "Hard to believe they were once priests.", completion = "Hopefully that will be enough to scare them off--at least for a while.", objectives = "Slay Soulbinder Sabeel and Duelist Xaheen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84761] = { id = 84761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Toil and Trespass", description = "Fennad picked a poor time to ask for my help. I'm leaving as soon as I recover my supplies from the Sufaadi. \n\nI was passing through when they attacked, and they could have killed me if Ruya hadn't carried me off. I followed them back to Sufaad, but there are too many for me to deal with. \n\nIf you help me recover my supplies, I'll see what I can do to help Fennad.", progress = "Hopefully they haven't used everything up.", completion = "Is this all you found? They didn't waste any time using up my supplies. Still, it's something.", objectives = "Recover Shahata's stolen supplies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84762] = { id = 84762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Are Our Words", description = "I had a necklace that our mother beaded. The Sufaadi took it when they robbed me. Things from old K'aresh are rare. If the Sufaadi haven't traded it, it'll be with their other valuables.\n\nI was planning to leave it behind. Sentimentality isn't worth risking your life, but you kept your word--which is more than I can say for my brother. Help me recover the necklace and it's yours.", progress = "What happened? Where's Fennad?", completion = "It's all gone. Months of supplies up in flames. If Fennad isn't dead already, he will be soon. The Sufaadi won't be forgiving, especially after what we've done.", objectives = "Help Shahata recover her mother's necklace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84765] = { id = 84765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Bonds and Boughs", description = "All that time in Tazavesh, all I could think about was coming home. Now it's only brought more grief. Even if the surveyor wasn't damaged, I still have nothing to trace back to our mother's grave.\n\n<Om'fennad glances around the cave.>\n\nSee these markings? This was a shrine to the Exchange. I guess it's a fitting place to finally say goodbye. Would you be willing to help one last time? Nothing dangerous--just light some incense.", completion = "After all this time, I thought it would feel different when we honored the oath. \n\nMaybe now's the time to stop thinking on the past. Thank you.", objectives = "Help Om'fennad and Shahata honor their mother.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84767] = { id = 84767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charred Celebration Crate", description = "<The crate is charred from fire, but the insides might be salvageable. Alyx would appreciate the supplies returned.>", progress = "Yes?", completion = "Oh, you found a missing crate! Wonderful!\n\nI really appreciate you returning these. If you find any more, please bring them to me.", objectives = "Return the Charred Celebration Crate to Alyx.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84773] = { id = 84773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystalized Celebration Crate", description = "<The crate is crystallized and can't be pried open easily. Alyx would appreciate the supplies returned.>", progress = "Yes?", completion = "Oh, you found a missing crate! Wonderful!\n\nI really appreciate you returning these. If you find any more, please bring them to me.", objectives = "Return the Crystallized Celebration Crate to Alyx.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84774] = { id = 84774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lorewalking" }
quests[84776] = { id = 84776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Call to Delves", description = "There are many treasures to be found in the delves around our land.\n\nPerhaps some could be of use to you.", progress = "Beware of whatever lurks in these delves.", completion = "You've survived! Fine work.", objectives = "Complete 5 Delves in Khaz Algar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84779] = { id = 84779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lorewalking: The Blade's Gambit", description = "Though now only a blade of little power, Xal'atath was not idle. In the aftermath of the Legion invasion, tensions between the Horde and the Alliance erupted into the Fourth War. \n\nXal'atath took advantage of the many forces at play in the war in a gambit to restore her power...", completion = "I believe the information my fellow Lorewalkers and I have found is completely new. I am unsure of its importance, but perhaps you can decide.", objectives = "Listen to Lorewalker Cho to learn the story of Xal'alath during the Fourth War.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84781] = { id = 84781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master of Secrets", objectives = "A fellow secret hunter I see! I was told to give you this. Good luck!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84782] = { id = 84782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lorewalking: The Blade's Past", description = "Many years ago, a stone tablet from Stormsong Valley made its way into my library. \n\nIt took years to break the cipher and translate the fragments of runes etched into it. \n\nI will tell you what we have pieced together. A tale of yet more treachery...", completion = "You are chosen, pitiful though you are. Be grateful.", objectives = "Listen to Cho to learn the story of Xal'alath in Ny'alotha.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84784] = { id = 84784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lorewalking: The Blade's Nemeses", description = "Lord N'Zoth calls now upon his brethren to aid in Xal'atath's defeat. You have been chosen to make the way for them to arrive.\n\nYou know what to do.", progress = "Do not waste Lord N'Zoth's time.", completion = "I have no doubt Lord N'Zoth could defeat this Xal'atath without the aid of his brethren, if only she had not infiltrated us so.", objectives = "Activate the 3 Ritual Obelisks to summon Yogg-Saron, C'Thun, and Y'Shaarj.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84787] = { id = 84787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Drain" }
quests[84788] = { id = 84788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hotrocket Hot Dogs" }
quests[84789] = { id = 84789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lorewalking: The Blade's Downfall", description = "They are ready. \n\nThe Lords hold Xal'atath within the keep. You are the pebble to trigger the avalanche of their power. To end Xal'atath. \n\nGo. Join them.", completion = "What did Xal'atath's last words to N'Zoth mean? Did she foresee their future collaboration?\n\nWas it her plan from the start?", objectives = "Confront Xal'atath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84791] = { id = 84791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hotrocket Burgers" }
quests[84820] = { id = 84820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By Oath and Blood", description = "After the Devouring, I didn't think I'd see Fennad again. At first, it was easier to stay angry at him for leaving than to grieve. Then it was easier to forget, to only focus on surviving the next day. Seeing him again brought everything back.\n\nOath-breaker... He had forsaken his oath to come home, but family is the first oath we're born to. What would it make me if I abandoned him now?\n\nHe's my brother--by oath and by blood. I won't leave him to the Sufaadi.", completion = "I almost didn't expect her to come for me, especially not like that. Even so, the surveyor's damaged and Shahata's supplies went up in flames. Maybe I shouldn't have come home.", objectives = "Rescue Om'fennad.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84821] = { id = 84821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Biological Quintainment", description = "Have earned spurs, now time use them!\n\nSlimes run off with joust dummies, but that just make for moving target. Better practice!\n\nMount noble mole steed by gate, get eye with lance, ride down slime.\n\nImportant skill for any knight, yes.", progress = "Watch out for big ones. Kick you good!", completion = "Ha! Lance just like boil, could hear pop from here.\n\nYou make good knight yet.", objectives = "Lance target dummy carrying slimes from mole-back.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84822] = { id = 84822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Iskaara", description = "Let's get these kids back to Iskaara, eh?\n\nI'll meet you there.", completion = "Ah, that's better. Got them all home and settled. My thanks!", objectives = "Meet Hemet Nesingwary in Iskaara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84826] = { id = 84826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eco-Dome: Rhovan", description = "I will not make excuses for what we did. I will carry the responsibility of it for the rest of my existence. Alleria will come to understand why it was necessary. When she sees the power of the All-Devouring, she will understand.\n\nWe will need at least two more Reshii Ribbons to bring enough of a force to bear against Dimensius. My friend Om'bera is a holder of a ribbon. She works in Eco-Dome: Rhovan on the next island. Let us gather her to our cause.", completion = "The dome is shattered and Om'bera may be in danger! I can see the scavengers from the wastelands of K'aresh within it now. \n\nOm'bera may yet live. We must find her, and her Reshii Ribbon.", objectives = "Meet Locus-Walker at Eco-Dome: Rhovan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84827] = { id = 84827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shattered Dome", description = "Eco-Dome: Rhovan was shattered by a falling chunk of void glass, destroying the structure and scattering its caretakers. They have returned to recover whatever equipment, flora, or fauna can be salvaged before the wastes claim them. \n\nSearch the ruins to find any clues of Overseer Om'bera's fate. We must have her Reshii Ribbon! Om'resh and I will search the impact crater.", progress = "Could Om'bera still be somewhere within the wreckage?", completion = "The Wastelanders killed Om'bera and took her Reshii Ribbon. These fallen oracles have harried all members of the Ravel since the Devouring War. This is a grim day.", objectives = "Search Eco-Dome: Rhovan for Om'bera.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84831] = { id = 84831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rhovan Infestation", description = "When the meteor struck, Om'bera and I tried to salvage what we could. Without the dome's shield, we were soon beset upon by scavengers of the Great Dark Beyond. We fled and were separated.\n\nSuch creatures are not of K'aresh, and hostile to the stable biomes we sought to achieve. We need to clear these invasive creatures to find our equipment, and Om'bera.", progress = "This was once a thriving eco-dome of the Trust. Our research worked toward the restoration of K'aresh.", completion = "Thank you. Those creatures would soon overwhelm us if left unchecked.\n\nIt's amazing they can survive without the protective barrier of the dome, without becoming energy as the K'areshi did. I wonder if such resilient traits could be transferred to the few native species in our domes?", objectives = "Kill 10 invasive creatures in Eco-Dome: Rhovan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84834] = { id = 84834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempest Clefts", description = "The Wastelanders were once the oracles of the Worldsoul of K'aresh. They were so proud and strident about their oaths. Now they scavenge the ruins like animals. Even rats have their uses. \n\nGather void cleft essences for me. I have an idea of how we might sway the fallen oracles to our cause.", progress = "Many denizens of the Void are voracious consumers of energy. They greedily flock to pockets of coalesced energy like moths to a flame.", completion = "Well done, my champion. We shall use this to draw out our prey.", objectives = "Bring 6 Void Cleft Essences to Xal'atath in the Tempest Fields.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84835] = { id = 84835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Drowned Lair" }
quests[84836] = { id = 84836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shuddering Hollow" }
quests[84838] = { id = 84838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies of Enemies", description = "The Wastelanders have made camp in the ruins of old K'aresh. A sanctuary from the ravenous beasts of the Void that stalk the wastes of K'aresh. A bulwark against outsiders.\n\nIf a hostile entity were to enter their camp, you could defeat it--then they would respect you. Take the void energy you gathered into the ruined tower north of here. Be ready!", progress = "You are not welcome here, stranger.", completion = "Dimensius destroyed K'aresh. Here in the wastes of Merciless K'aresh, we mete out punishment for all who failed him. You say your oaths align with ours? Let us talk.", objectives = "Place the coalesced void energy in the Castigar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84848] = { id = 84848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Before the Void", description = "You've impressed these Wastelanders with your violent prowess, my champion. Well done. Now let me do my work.\n\nI know what these former oracles want. They dream of hearing the Song of K'aresh once more. I must make them believe it is possible, then pull on that string of desire. Soon we will have our army, and another Reshii Ribbon.\n\nFirst, let's return the Tabiqa ritual dagger.", completion = "We would gladly war against the Shadowguard. But I cannot give up this Reshii Ribbon to someone I don't trust.\n\nPromises of revenge are easy. Trust is hard won among the Wastelanders.", objectives = "Convince Soul-Scribe to join forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84850] = { id = 84850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Serpent's Wrath" }
quests[84851] = { id = 84851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tides of Greed" }
quests[84852] = { id = 84852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legacy of the Vrykul" }
quests[84855] = { id = 84855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dead Silence", description = "Dimensius's power is so great that even shattered, his aura radiates a power debilitating to mortal life. It is why the K'areshi were changed to beings of energy--it was the only way we could survive his presence.\n\nI had hoped my scouts could find a path that was safe for you and your compatriots to enter the manaforge. Raz'ida, Lo'shah, and Yanhal should have met us by now. Find them for me. Their information is vital to our defense against the All-Devouring.", completion = "Raz'ida was a Shadowguard agent? I've trusted her for thousands of years. How did they break her loyalty? \n\nIf she could be turned, then any of the Trust's agents could as well. It is vital that we get the information about their base, and we can only rely upon the four of us to do so.", objectives = "Find the scouts at Overlook Zo'Shuul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[84856] = { id = 84856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where the Void Gathers", description = "With Locus-Walker's Reshii Ribbon, I can transmute your flesh to energy. It won't hurt much.\n\nYou will have the ability to travel within Dimensius's aura without being destroyed. There you can search for a path into the manaforge. You will travel in Untethered Space as a creature of energy, ignored by the Shadowguard. Their void beasts however... stay well away or be devoured. \n\nTalk to me when you are ready. Time is of the essence.", progress = "We will need more than one Reshii Ribbon if we want to reach Dimensius with a force capable of stopping his emergence.", completion = "Through this, you have learned what I already knew. \n\nDimensius is a terrible threat. We must work together, {name}, if we are to survive.", objectives = "Search Shadow Point in Untethered Space with Xal'atath's help.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
